from pathlib import Path

path = Path('public/index.html')
if not path.exists():
    raise SystemExit('public/index.html não encontrado')

html = path.read_text(encoding='utf-8')
marker = '<!-- Smyle Lab V63: favicon oficial -->'
icon64 = ''

links = f'''<!-- Smyle Lab V63: favicon oficial -->\n<link rel="icon" type="image/png" sizes="64x64" href="data:image/png;base64,{icon64}">\n<link rel="shortcut icon" type="image/png" href="data:image/png;base64,{icon64}">\n<meta name="theme-color" content="#61D7D3">\n'''

if marker not in html:
    head_close = html.find('</head>')
    if head_close < 0:
        raise RuntimeError('Fechamento </head> principal não encontrado.')
    html = html[:head_close] + links + html[head_close:]

path.write_text(html, encoding='utf-8')
print('V63 aplicada: favicon oficial Smyle configurado diretamente no HTML.')
